function escapeEditorHtml(value=''){
  return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
}
function markdownToHtml(value=''){
  let s=escapeEditorHtml(value);
  s=s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2">$1</a>');
  return s.replace(/\n/g,'<br>');
}
function normalizeEmailEditorValue(value=''){
  const s=String(value||'');
  return /<(?:a|strong|b|em|i|u|br|p|div|ul|ol|li)\b/i.test(s) ? s : markdownToHtml(s);
}
function RichEmailEditor({value,onChange,placeholder='Write your email…',rows=12}){
  const ref=useRef(null);
  useEffect(()=>{
    if(!ref.current)return;
    const next=normalizeEmailEditorValue(value);
    if(ref.current.innerHTML!==next)ref.current.innerHTML=next;
  },[value]);
  function command(name,arg=null){
    ref.current?.focus();
    document.execCommand(name,false,arg);
    onChange(ref.current?.innerHTML||'');
  }
  function addLink(e){
    e.preventDefault();
    ref.current?.focus();
    const sel=window.getSelection();
    if(!sel || sel.rangeCount===0 || sel.toString().trim()===''){
      alert('Select the exact words you want to make clickable first. For example, select “Google Play”.');
      return;
    }
    const url=window.prompt('URL (https://...)');
    if(!url)return;
    if(!/^https?:\/\//i.test(url)){alert('Please enter a URL starting with http:// or https://');return;}
    document.execCommand('createLink',false,url.trim());
    onChange(ref.current?.innerHTML||'');
  }
  const textSize=Math.max(120,Number(rows||12)*24);
  return <div className="border border-slate-300 rounded-xl overflow-hidden bg-white">
    <div className="flex flex-wrap items-center gap-1 p-2 border-b bg-slate-50">
      <button type="button" title="Bold" className="icon-btn" onMouseDown={e=>{e.preventDefault();command('bold')}}><Bold size={16}/></button>
      <button type="button" title="Italic" className="icon-btn" onMouseDown={e=>{e.preventDefault();command('italic')}}><Italic size={16}/></button>
      <button type="button" title="Underline" className="icon-btn" onMouseDown={e=>{e.preventDefault();command('underline')}}><Underline size={16}/></button>
      <button type="button" title="Add link to selected text" className="btn btn-secondary text-sm flex items-center gap-2" onMouseDown={addLink}><LinkIcon size={15}/>Link</button>
      <span className="text-xs text-slate-500 ml-2">Select words, then use Link. Formatting is preserved in the recipient’s email.</span>
    </div>
    <div ref={ref} contentEditable suppressContentEditableWarning className="w-full p-3 outline-none overflow-y-auto leading-6" style={{minHeight:textSize}} data-placeholder={placeholder}
      onInput={()=>onChange(ref.current?.innerHTML||'')}
      onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();command('bold')}}}
    />
  </div>;
}

function App(){
  const [user,setUser]=useState(()=>JSON.parse(localStorage.getItem('user')||'null'));
  if(!user) return <Auth onLogin={u=>setUser(u)}/>;
  return <Shell user={user} onLogout={()=>{localStorage.clear();setUser(null)}}/>;
}

function Auth({onLogin}){
  const [mode,setMode]=useState('login');
  const [form,setForm]=useState({name:'',email:'',password:''});
  const [err,setErr]=useState('');
  const [loading,setLoading]=useState(false);
  async function submit(e){e.preventDefault();setErr('');setLoading(true);try{const {data}=await api.post(`/auth/${mode}`,form);localStorage.setItem('token',data.token);localStorage.setItem('user',JSON.stringify(data.user));onLogin(data.user)}catch(x){setErr(x.response?.data?.message||'Something went wrong')}finally{setLoading(false)}}
  return <div className="min-h-screen grid place-items-center p-6 bg-slate-50"><form onSubmit={submit} className="card w-full max-w-md p-8 shadow-sm"><h1 className="text-3xl font-extrabold">JobTrack</h1><p className="text-slate-500 mt-1 mb-7">Your job search command center.</p>{mode==='register'&&<input className="input mb-3" required placeholder="Name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/>}<input className="input mb-3" required type="email" placeholder="Email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/><input className="input mb-4" required minLength={8} type="password" placeholder="Password (min 8 characters)" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/>{err&&<p className="text-red-600 text-sm mb-3">{err}</p>}<button disabled={loading} className="btn btn-primary w-full disabled:opacity-50">{loading?'Please wait…':mode==='login'?'Login':'Create account'}</button><button type="button" className="w-full mt-4 text-sm text-indigo-600" onClick={()=>{setMode(mode==='login'?'register':'login');setErr('')}}>{mode==='login'?'Create an account':'Already have an account? Login'}</button></form></div>
}

function Shell({user,onLogout}){
  const [page,setPage]=useState('dashboard');
  const [notificationCount,setNotificationCount]=useState(0);
  const nav=[['dashboard','Dashboard',LayoutDashboard],['applications','Applications',BriefcaseBusiness],['emails','Emails',Mail],['templates','Templates',FilePlus2],['contacts','Contacts',Users],['calls','Calls',PhoneCall],['import','Import Excel',FileSpreadsheet],['settings','Settings',Settings]];
  const refreshNotifications=()=>api.get('/notifications').then(r=>setNotificationCount(r.data.filter(n=>!n.read).length)).catch(()=>{});
  useEffect(()=>{refreshNotifications();const id=setInterval(refreshNotifications,30000);return()=>clearInterval(id)},[]);
  return <div className="min-h-screen bg-slate-50">
    <aside className="fixed inset-y-0 left-0 w-64 bg-white border-r border-slate-200 p-5 hidden md:block z-20"><div className="text-xl font-extrabold mb-8">JobTrack</div>{nav.map(([id,label,I])=><button key={id} onClick={()=>setPage(id)} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl mb-1 ${page===id?'bg-slate-900 text-white':'text-slate-600 hover:bg-slate-100'}`}><I size={18}/>{label}</button>)}<button onClick={()=>setPage('notifications')} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl mb-1 ${page==='notifications'?'bg-slate-900 text-white':'text-slate-600 hover:bg-slate-100'}`}><Bell size={18}/>Notifications{notificationCount>0&&<span className="ml-auto min-w-5 h-5 px-1 rounded-full bg-red-500 text-white text-xs grid place-items-center">{notificationCount}</span>}</button><button onClick={onLogout} className="absolute bottom-6 flex items-center gap-3 text-slate-500 px-3"><LogOut size={18}/>Logout</button></aside>
    <main className="md:ml-64 p-5 md:p-8 max-w-[1500px]"><header className="flex justify-between items-center mb-8"><div><p className="text-sm text-slate-500">Welcome back</p><h2 className="text-2xl font-bold">{user.name}</h2></div><button onClick={()=>setPage('notifications')} className="relative p-3 bg-white border rounded-xl hover:bg-slate-50"><Bell size={19}/>{notificationCount>0&&<span className="absolute -top-1 -right-1 min-w-5 h-5 px-1 rounded-full bg-red-500 text-white text-xs grid place-items-center">{notificationCount}</span>}</button></header>
      {page==='dashboard'&&<Dashboard/>}{page==='applications'&&<Applications/>}{page==='emails'&&<Emails/>}{page==='templates'&&<Templates/>}{page==='contacts'&&<Contacts/>}{page==='calls'&&<Calls/>}{page==='import'&&<ImportExcel/>}{page==='notifications'&&<Notifications onChange={refreshNotifications}/>} {page==='settings'&&<SettingsPage user={user} onDeleted={onLogout}/>} 
    </main>
  </div>
}

function Dashboard(){const [d,setD]=useState(null);const load=()=>api.get('/dashboard').then(r=>setD(r.data));useEffect(()=>{load()},[]);if(!d)return <Loading/>;const cards=[['Applications',d.totalApplications],['Emails',d.totalEmails],['Opened',d.openEmails],['Replies',d.repliedEmails]];return <><div className="flex justify-between items-end mb-6"><div><h1 className="text-3xl font-bold">Dashboard</h1><p className="text-slate-500">Track your pipeline and outreach.</p></div></div><div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">{cards.map(([x,v])=><div className="card p-5" key={x}><p className="text-sm text-slate-500">{x}</p><p className="text-3xl font-bold mt-2">{v}</p></div>)}</div><div className="card p-6"><h3 className="font-bold mb-4">Application pipeline</h3><div className="grid grid-cols-2 md:grid-cols-4 gap-3">{statuses.map(s=><div className="bg-slate-50 rounded-xl p-4" key={s}><p className="text-xs text-slate-500">{s}</p><p className="text-2xl font-bold mt-1">{d.byStatus[s]||0}</p></div>)}</div></div></>}

function Applications(){
  const [apps,setApps]=useState([]),[show,setShow]=useState(false),[search,setSearch]=useState('');
  const [form,setForm]=useState(emptyApplication);const [saving,setSaving]=useState(false);
  const load=()=>api.get('/applications').then(r=>setApps(r.data)).catch(()=>{});
  useEffect(()=>{load()},[]);
  function updateCompany(field,value){setForm(f=>({...f,company:{...f.company,[field]:value}}))}
  function updateJob(field,value){setForm(f=>({...f,job:{...f.job,[field]:value}}))}
  function reset(){setForm({...emptyApplication,company:{...emptyApplication.company},job:{...emptyApplication.job},appliedAt:new Date().toISOString().slice(0,10)});}
  async function save(e){
    e.preventDefault();setSaving(true);
    try{await api.post('/applications',form);setShow(false);reset();await load()}
    catch(x){alert(x.response?.data?.message||x.userMessage||'Could not save application')}
    finally{setSaving(false)}
  }
  const filtered=apps.filter(a=>`${a.jobId?.companyId?.name||''} ${a.jobId?.title||''}`.toLowerCase().includes(search.toLowerCase()));
  return <>
    <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-6">
      <div><h1 className="text-3xl font-bold">Applications</h1><p className="text-slate-500">Add the company, job and application together in one step.</p></div>
      <button onClick={()=>{reset();setShow(true)}} className="btn btn-primary flex gap-2 items-center"><Plus size={17}/>Add Application</button>
    </div>
    <div className="card p-3 mb-4 flex items-center gap-2"><Search size={18} className="text-slate-400"/><input className="outline-none w-full bg-transparent" placeholder="Search company or role…" value={search} onChange={e=>setSearch(e.target.value)}/></div>
    {show&&<Modal title="Add application" onClose={()=>!saving&&setShow(false)}>
      <form onSubmit={save} className="space-y-5">
        <section><h3 className="font-semibold mb-3">Company</h3><div className="grid md:grid-cols-2 gap-3"><input className="input" required placeholder="Company name *" value={form.company.name} onChange={e=>updateCompany('name',e.target.value)}/><input className="input" placeholder="Website" value={form.company.website} onChange={e=>updateCompany('website',e.target.value)}/><input className="input" placeholder="Industry" value={form.company.industry} onChange={e=>updateCompany('industry',e.target.value)}/><input className="input" placeholder="Company notes" value={form.company.notes} onChange={e=>updateCompany('notes',e.target.value)}/></div><p className="text-xs text-slate-500 mt-2">If this company already exists, JobTrack will reuse it.</p></section>
        <section><h3 className="font-semibold mb-3">Job</h3><div className="grid md:grid-cols-2 gap-3"><input className="input md:col-span-2" required placeholder="Job title *" value={form.job.title} onChange={e=>updateJob('title',e.target.value)}/><input className="input" placeholder="Location" value={form.job.location} onChange={e=>updateJob('location',e.target.value)}/><input className="input" placeholder="Job type (Full-time, Internship…)" value={form.job.jobType} onChange={e=>updateJob('jobType',e.target.value)}/><input className="input" placeholder="Job ID" value={form.job.jobId} onChange={e=>updateJob('jobId',e.target.value)}/><input className="input" placeholder="Source (LinkedIn, company site…)" value={form.job.source} onChange={e=>updateJob('source',e.target.value)}/><input className="input" placeholder="Salary" value={form.job.salary} onChange={e=>updateJob('salary',e.target.value)}/><input className="input" placeholder="Job URL" type="url" value={form.job.jobUrl} onChange={e=>updateJob('jobUrl',e.target.value)}/><textarea className="input md:col-span-2" rows="3" placeholder="Job description" value={form.job.description} onChange={e=>updateJob('description',e.target.value)}/><textarea className="input md:col-span-2" rows="3" placeholder="Requirements" value={form.job.requirements} onChange={e=>updateJob('requirements',e.target.value)}/></div><p className="text-xs text-slate-500 mt-2">If the same job already exists for this company, JobTrack will reuse it.</p></section>
        <section><h3 className="font-semibold mb-3">Application</h3><div className="grid md:grid-cols-2 gap-3"><select className="input" value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{statuses.map(s=><option key={s}>{s}</option>)}</select><input className="input" type="date" value={form.appliedAt} onChange={e=>setForm({...form,appliedAt:e.target.value})}/><textarea className="input md:col-span-2" rows="4" placeholder="Application notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></div></section>
        <button disabled={saving} className="btn btn-primary w-full">{saving?'Saving application…':'Save application'}</button>
      </form>
    </Modal>}
    <div className="card overflow-hidden"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="text-left p-4">Company</th><th className="text-left p-4">Role</th><th className="text-left p-4">Status</th><th className="text-left p-4">Applied</th></tr></thead><tbody>{filtered.map(a=><tr className="border-t" key={a._id}><td className="p-4 font-semibold">{a.jobId?.companyId?.name||'—'}</td><td className="p-4">{a.jobId?.title||'—'}</td><td className="p-4"><span className="px-2.5 py-1 rounded-full bg-slate-100">{a.status}</span></td><td className="p-4">{a.appliedAt?new Date(a.appliedAt).toLocaleDateString():'—'}</td></tr>)}</tbody></table>{!filtered.length&&<div className="p-10 text-center text-slate-500">No applications yet. Click Add Application to enter the company, job and application together.</div>}</div></div>
  </>;
}

function CompanyModal({onClose,onSaved}){const [form,setForm]=useState(emptyCompany),[saving,setSaving]=useState(false),[err,setErr]=useState('');async function save(e){e.preventDefault();setSaving(true);setErr('');try{await api.post('/companies',form);onSaved();onClose()}catch(x){setErr(x.response?.data?.message||'Could not create company')}finally{setSaving(false)}}return <Modal title="Add company" onClose={onClose}><form onSubmit={save} className="space-y-3"><input className="input" required placeholder="Company name *" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input className="input" placeholder="Website" value={form.website} onChange={e=>setForm({...form,website:e.target.value})}/><input className="input" placeholder="Industry" value={form.industry} onChange={e=>setForm({...form,industry:e.target.value})}/><textarea className="input" placeholder="Notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/>{err&&<p className="text-sm text-red-600">{err}</p>}<button disabled={saving} className="btn btn-primary w-full">{saving?'Saving…':'Save company'}</button></form></Modal>}

function JobModal({companies,onClose,onSaved,onCreateCompany}){const [form,setForm]=useState(emptyJob),[saving,setSaving]=useState(false),[err,setErr]=useState('');async function save(e){e.preventDefault();setSaving(true);setErr('');try{await api.post('/jobs',form);onSaved();onClose()}catch(x){setErr(x.response?.data?.message||'Could not create job')}finally{setSaving(false)}}return <Modal title="Add job" onClose={onClose}><form onSubmit={save} className="space-y-3"><div className="flex gap-2"><select className="input" required value={form.companyId} onChange={e=>setForm({...form,companyId:e.target.value})}><option value="">Select company *</option>{companies.map(c=><option key={c._id} value={c._id}>{c.name}</option>)}</select><button type="button" className="icon-btn" title="Create company" onClick={onCreateCompany}><Plus size={18}/></button></div><input className="input" required placeholder="Job title *" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><div className="grid md:grid-cols-2 gap-3"><input className="input" placeholder="Location" value={form.location} onChange={e=>setForm({...form,location:e.target.value})}/><input className="input" placeholder="Job type (Full-time, Internship…)" value={form.jobType} onChange={e=>setForm({...form,jobType:e.target.value})}/><input className="input" placeholder="Job ID" value={form.jobId} onChange={e=>setForm({...form,jobId:e.target.value})}/><input className="input" placeholder="Source (LinkedIn, company site…)" value={form.source} onChange={e=>setForm({...form,source:e.target.value})}/><input className="input" placeholder="Salary" value={form.salary} onChange={e=>setForm({...form,salary:e.target.value})}/><input className="input" placeholder="Job URL" type="url" value={form.jobUrl} onChange={e=>setForm({...form,jobUrl:e.target.value})}/></div><textarea className="input" rows="3" placeholder="Job description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><textarea className="input" rows="3" placeholder="Requirements" value={form.requirements} onChange={e=>setForm({...form,requirements:e.target.value})}/>{err&&<p className="text-sm text-red-600">{err}</p>}<button disabled={saving} className="btn btn-primary w-full">{saving?'Saving…':'Save job'}</button></form></Modal>}

