const callOutcomes=['Not Called','No Answer','Busy','Call Back Later','Spoke','Interested','Not Interested','Wrong Number','Switched Off','Out of Coverage','Voicemail','Number Not Available','Do Not Call','Other'];
function Calls(){
 const [calls,setCalls]=useState([]),[contacts,setContacts]=useState([]),[apps,setApps]=useState([]),[show,setShow]=useState(false),[search,setSearch]=useState('');
 const [form,setForm]=useState({contactId:'',applicationId:'',phone:'',outcome:'Not Called',notes:'',calledAt:'',nextCallAt:''});
 const load=()=>Promise.all([api.get('/calls'),api.get('/contacts'),api.get('/applications')]).then(([c,co,a])=>{setCalls(c.data);setContacts(co.data);setApps(a.data)}).catch(()=>{});useEffect(()=>{load()},[]);
 function selectContact(id){const c=contacts.find(x=>x._id===id);setForm(f=>({...f,contactId:id,phone:c?.phone||f.phone}))}
 async function save(e){e.preventDefault();try{await api.post('/calls',form);setShow(false);setForm({contactId:'',applicationId:'',phone:'',outcome:'Not Called',notes:'',calledAt:'',nextCallAt:''});load()}catch(x){alert(x.response?.data?.message||'Could not save call')}}
 const filtered=calls.filter(c=>`${c.contactId?.name||''} ${c.contactId?.phone||c.phone||''} ${c.outcome||''} ${c.contactId?.companyId?.name||''}`.toLowerCase().includes(search.toLowerCase()));
 return <><div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-6"><div><h1 className="text-3xl font-bold">Calls</h1><p className="text-slate-500">Track every call attempt and real-world outcome.</p></div><button onClick={()=>setShow(true)} className="btn btn-primary flex gap-2 items-center"><PhoneCall size={17}/>Log call</button></div><div className="card p-3 mb-4 flex items-center gap-2"><Search size={18} className="text-slate-400"/><input className="outline-none w-full bg-transparent" placeholder="Search person, phone or outcome…" value={search} onChange={e=>setSearch(e.target.value)}/></div>{show&&<Modal title="Log a call" onClose={()=>setShow(false)}><form onSubmit={save} className="space-y-3"><select required className="input" value={form.contactId} onChange={e=>selectContact(e.target.value)}><option value="">Select contact *</option>{contacts.map(c=><option key={c._id} value={c._id}>{c.name}{c.phone?` — ${c.phone}`:''}</option>)}</select><input required className="input" placeholder="Phone number *" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/><select className="input" value={form.applicationId} onChange={e=>setForm({...form,applicationId:e.target.value})}><option value="">No application</option>{apps.map(a=><option key={a._id} value={a._id}>{a.jobId?.companyId?.name} — {a.jobId?.title}</option>)}</select><select className="input" value={form.outcome} onChange={e=>setForm({...form,outcome:e.target.value})}>{callOutcomes.map(x=><option key={x}>{x}</option>)}</select><label className="text-sm text-slate-600">Call date/time<input className="input mt-1" type="datetime-local" value={form.calledAt} onChange={e=>setForm({...form,calledAt:e.target.value})}/></label><label className="text-sm text-slate-600">Next call / reminder (optional)<input className="input mt-1" type="datetime-local" value={form.nextCallAt} onChange={e=>setForm({...form,nextCallAt:e.target.value})}/></label><textarea className="input" rows="4" placeholder="Notes: what happened, who answered, next steps…" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/><button className="btn btn-primary w-full">Save call</button></form></Modal>}<div className="grid gap-3">{filtered.map(c=><div className="card p-5" key={c._id}><div className="flex flex-col md:flex-row md:justify-between gap-3"><div><p className="font-bold">{c.contactId?.name||'Unknown contact'}</p><p className="text-sm text-slate-500 flex items-center gap-1 mt-1"><Phone size={14}/>{c.phone}</p>{c.contactId?.companyId?.name&&<p className="text-xs text-slate-400 mt-1">{c.contactId.companyId.name}</p>}</div><span className="px-3 py-1 rounded-full bg-slate-100 h-fit text-sm">{c.outcome}</span></div><div className="mt-3 text-sm text-slate-600">{c.notes||'No notes'}</div><div className="mt-3 flex flex-wrap gap-4 text-xs text-slate-400"><span>Called: {c.calledAt?new Date(c.calledAt).toLocaleString():'Not yet'}</span>{c.nextCallAt&&<span>Next: {new Date(c.nextCallAt).toLocaleString()}</span>}</div></div>)}{!filtered.length&&<div className="card p-10 text-center text-slate-500">No call records yet.</div>}</div></>;
}

function ImportExcel(){
 const fields=[['name','Contact name'],['email','Email'],['phone','Phone'],['designation','Designation'],['linkedinUrl','LinkedIn'],['company','Company'],['website','Company website'],['industry','Industry'],['jobTitle','Job title'],['location','Job location'],['jobType','Job type'],['jobUrl','Job URL'],['jobId','Job ID / Requisition'],['salary','Salary / CTC'],['source','Job source'],['status','Application status'],['appliedAt','Applied date'],['notes','Notes'],['emailSubject','Email subject'],['emailBody','Email body']];
 const [file,setFile]=useState(null),[busy,setBusy]=useState(false),[preview,setPreview]=useState(null),[mapping,setMapping]=useState({}),[createDrafts,setCreateDrafts]=useState(false),[result,setResult]=useState(null);
 async function previewFile(e){e.preventDefault();if(!file)return;setBusy(true);setResult(null);try{const fd=new FormData();fd.append('file',file);const {data}=await api.post('/import/preview',fd,{headers:{'Content-Type':'multipart/form-data'}});setPreview(data);setMapping(data.suggestedMapping||{})}catch(x){setResult({message:x.response?.data?.message||x.userMessage||'Could not read spreadsheet'})}finally{setBusy(false)}}
 async function importData(){setBusy(true);setResult(null);try{const fd=new FormData();fd.append('file',file);fd.append('mapping',JSON.stringify(mapping));fd.append('createEmailDrafts',String(createDrafts));const {data}=await api.post('/import/excel',fd,{headers:{'Content-Type':'multipart/form-data'}});setResult(data)}catch(x){setResult({message:x.response?.data?.message||x.userMessage||'Import failed'})}finally{setBusy(false)}}
 return <><div className="mb-6"><h1 className="text-3xl font-bold">Import Excel</h1><p className="text-slate-500">Preview and map your spreadsheet before anything is created. Import never sends emails automatically.</p></div>
 <div className="card p-6 max-w-5xl">
  {!preview&&<form onSubmit={previewFile} className="space-y-4"><div className="border-2 border-dashed border-slate-200 rounded-2xl p-8 text-center"><Upload className="mx-auto mb-3 text-slate-400"/><p className="font-semibold">Choose .xlsx, .xls or .csv</p><p className="text-xs text-slate-500 mt-1">You can use your own column names. JobTrack will suggest mappings and you can correct every field before import.</p><input className="mt-4 block mx-auto" type="file" accept=".xlsx,.xls,.csv" onChange={e=>setFile(e.target.files?.[0]||null)}/>{file&&<p className="text-sm mt-3">Selected: {file.name}</p>}</div><button disabled={!file||busy} className="btn btn-primary w-full disabled:opacity-50">{busy?'Reading…':'Preview spreadsheet'}</button></form>}
  {preview&&<div className="space-y-6"><div className="flex flex-col md:flex-row md:justify-between gap-3"><div><h2 className="text-xl font-bold">Review column mapping</h2><p className="text-sm text-slate-500">{preview.rows} rows detected. Check the mapping before importing.</p></div><button className="btn btn-secondary" onClick={()=>{setPreview(null);setResult(null)}}>Choose another file</button></div>
   <div className="grid md:grid-cols-2 gap-3">{fields.map(([field,label])=><label className="text-sm text-slate-600" key={field}>{label}<select className="input mt-1" value={mapping[field]||''} onChange={e=>setMapping({...mapping,[field]:e.target.value})}><option value="">— Not mapped —</option>{preview.headers.map(h=><option key={h} value={h}>{h}</option>)}</select></label>)}</div>
   <div className="border rounded-xl overflow-auto"><table className="w-full text-sm"><thead className="bg-slate-50"><tr>{preview.headers.map(h=><th className="text-left p-3 whitespace-nowrap" key={h}>{h}</th>)}</tr></thead><tbody>{preview.sample.map((row,i)=><tr key={i} className="border-t">{preview.headers.map(h=><td className="p-3 whitespace-nowrap max-w-xs truncate" key={h}>{String(row[h]??'')}</td>)}</tr>)}</tbody></table></div>
   <label className="flex items-start gap-3 p-4 bg-slate-50 rounded-xl"><input type="checkbox" className="mt-1" checked={createDrafts} onChange={e=>setCreateDrafts(e.target.checked)}/><span><span className="font-semibold block">Create email drafts for imported email addresses</span><span className="text-sm text-slate-500">Drafts only. <strong>No emails will be sent during import.</strong> You will review and send them later from Emails.</span></span></label>
   <button disabled={busy} className="btn btn-primary w-full" onClick={importData}>{busy?'Importing…':'Confirm import'}</button>
  </div>}
  {result&&<div className="mt-5 bg-slate-50 rounded-xl p-4"><p className="font-semibold">{result.message}</p>{result.rows&&<div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-4 text-sm">{[['Contacts created',result.contactsCreated],['Contacts updated',result.contactsUpdated],['Companies',result.companiesCreated],['Jobs',result.jobsCreated],['Applications',result.applicationsCreated],['Email drafts',result.draftsCreated],['Emails sent',result.emailsSent||0]].map(([k,v])=><div key={k}><p className="text-slate-500">{k}</p><p className="text-xl font-bold">{v}</p></div>)}</div>}{result.errors?.length>0&&<div className="mt-4 text-sm text-red-600">{result.errors.slice(0,20).map((e,i)=><p key={i}>Row {e.row}: {e.message}</p>)}</div>}</div>}
 </div></>;
}
function SettingsPage({user,onDeleted}){
 const [status,setStatus]=useState(null),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');
 async function load(){try{const {data}=await api.get('/gmail/status');setStatus(data)}catch(e){setMsg(e.response?.data?.message||'Could not load Gmail status')}}
 useEffect(()=>{load();const p=new URLSearchParams(window.location.search);if(p.get('gmail')){setMsg(p.get('gmail')==='connected'?'Gmail connected successfully.':`Gmail connection failed: ${p.get('message')||'Unknown error'}`);window.history.replaceState({},'',window.location.pathname)}},[]);
 async function connect(){setBusy(true);setMsg('');try{const {data}=await api.get('/gmail/connect');window.location.href=data.url}catch(e){setMsg(e.response?.data?.message||e.userMessage||'Could not start Google authorization')}finally{setBusy(false)}}
 async function disconnect(){if(!confirm('Disconnect Gmail from JobTrack? Existing email history will remain.'))return;setBusy(true);try{await api.post('/gmail/disconnect');await load();setMsg('Gmail disconnected.')}catch(e){setMsg(e.response?.data?.message||'Could not disconnect Gmail')}finally{setBusy(false)}}
 async function deleteAccount(){
   const phrase=window.prompt('This permanently deletes your JobTrack account, Gmail connection, emails, templates, contacts, applications, calls and tracking data. Type DELETE to confirm.');
   if(phrase!=='DELETE')return;
   setBusy(true);setMsg('');
   try{await api.delete('/auth/account');localStorage.clear();onDeleted?.();}
   catch(e){setMsg(e.response?.data?.message||'Could not delete account');setBusy(false)}
 }
 return <><div className="mb-6"><h1 className="text-3xl font-bold">Settings</h1><p className="text-slate-500">Connect your personal Gmail account. JobTrack sends through Gmail, not Resend.</p></div><div className="card p-6 max-w-2xl"><div className="flex items-start gap-4"><div className="w-12 h-12 rounded-xl bg-red-50 grid place-items-center text-red-600"><Mail size={22}/></div><div className="flex-1"><h2 className="text-xl font-bold">Gmail</h2><p className="text-sm text-slate-500 mt-1">Send emails from your actual Gmail address and let JobTrack sync replies.</p>{status?.connected?<><div className="mt-4 p-4 bg-emerald-50 rounded-xl"><p className="font-semibold text-emerald-800">Connected</p><p className="text-sm text-emerald-700 mt-1">{status.email}</p><p className="text-xs text-emerald-700 mt-1">Connected {new Date(status.connectedAt).toLocaleString()}</p></div><button disabled={busy} onClick={disconnect} className="btn btn-secondary mt-4">Disconnect Gmail</button></>:<button disabled={busy} onClick={connect} className="btn btn-primary mt-4">{busy?'Opening Google…':'Connect Gmail'}</button>}<div className="mt-5 text-xs text-slate-500 space-y-1"><p>• JobTrack never needs your Gmail password.</p><p>• Google OAuth grants Gmail access to the backend using a refresh token.</p><p>• Email import creates drafts only; nothing is sent automatically.</p><p>• Reply detection checks your inbox periodically and stops automatic follow-up when a matching reply is found.</p></div>{msg&&<p className="mt-4 text-sm text-slate-700 bg-slate-50 p-3 rounded-xl">{msg}</p>}</div></div></div>
 <div className="card p-6 max-w-2xl mt-6 border-red-200"><h2 className="text-xl font-bold text-red-700">Delete account</h2><p className="text-sm text-slate-500 mt-2">Permanently delete your JobTrack account and all data associated with it, including applications, companies, jobs, contacts, calls, emails, tracking events, templates, notifications and the Gmail connection.</p><button disabled={busy} onClick={deleteAccount} className="btn btn-secondary mt-4 text-red-600 border-red-200 hover:bg-red-50"><Trash2 size={16}/>Delete my account</button></div></>;
}

function Notifications({onChange}){const [ns,setNs]=useState([]);const load=()=>api.get('/notifications').then(r=>setNs(r.data));useEffect(()=>{load()},[]);async function markRead(id){await api.patch(`/notifications/${id}/read`);load();onChange?.()}return <><h1 className="text-3xl font-bold mb-2">Notifications</h1><p className="text-slate-500 mb-6">Follow-ups and email activity.</p><div className="grid gap-3">{ns.map(n=><div className={`card p-5 ${n.read?'opacity-60':''}`} key={n._id}><div className="flex justify-between gap-4"><div><p className="font-semibold">{n.title}</p><p className="text-sm text-slate-500 mt-1">{n.message}</p>{!n.read&&<button onClick={()=>markRead(n._id)} className="text-sm text-indigo-600 mt-3 inline-flex items-center gap-1"><CheckCircle2 size={15}/>Mark as read</button>}</div><span className="text-xs text-slate-400 whitespace-nowrap">{new Date(n.createdAt).toLocaleString()}</span></div></div>)}{!ns.length&&<div className="card p-10 text-center text-slate-500">No notifications.</div>}</div></>}

function Modal({title,children,onClose}){return <div className="fixed inset-0 bg-slate-950/45 z-50 flex items-center justify-center p-4" onMouseDown={e=>{if(e.target===e.currentTarget)onClose?.()}}><div className="bg-white rounded-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-xl"><div className="flex justify-between items-center mb-5"><h2 className="text-xl font-bold">{title}</h2><button type="button" onClick={onClose} className="icon-btn" aria-label="Close"><X size={20}/></button></div>{children}</div></div>}
function Loading(){return <div className="card p-10 text-center text-slate-500">Loading…</div>}

createRoot(document.getElementById('root')).render(<BrowserRouter><App/></BrowserRouter>);
